  str_pet_skin_name_1602183 = "野心深き誘い",
  str_pet_skin_name_1500973 = "冷たい刃先",
  str_pet_skin_name_1400953 = "妖しき侠気",
  str_pet_skin_desc_1500333 = "潮汐祭に参加するバイスが自分のために選んだ、シンプル・スポーティな水着。バイスが着やすいよう尻尾を自由に振れる特殊な構造デザインが用いられている。よく観察してみると、特殊な構造のほかにも黒と金の配色の日焼け防止ジャケットが付いており、元気よく動き回る彼女にはぴったりのデザインとなっている。ガチャガチャと音を立てる製氷機の隣で、満面の笑みを浮かべたショートヘアの少女が水遊びに誘う。ビーチバレー、冷たいドリンク、かき氷のワゴン…この夏、あなたとバイスが過ごした2人だけの思い出がたっぷりと詰め込まれている。",
  str_pet_skin_desc_1600063 = "潮汐祭をテーマにデザインされた、乙女らしい白い水着。白夜城の高貴で優雅なレースアップデザインが用いられている。海風に揺れるベールが少女の肌を灼熱の太陽から守ってくれる。カレンはいつもペンダントをどう合わせるか悩んでいたが、この水着ではその問題も完璧に解決されている。カレン曰く、この水着を着ている間は貴族の身分によるしがらみをしばらく忘れ、少女として爽やかな夏を楽しむことができるそうだ。",
  str_pet_skin_desc_1601033 = "エルシーが一目で魅了された小悪魔シリーズの水着。メタリックチェーン、ハート型の眼帯、ブラックゴールドのシュシュ…全体的に、上品かつゴージャスなディテールが施されている。それでいて、ダークな色合いで丸みを帯びたレース模様と複雑に編まれた紐状のデザインが全体に遊び心を際立たせている。さらに、巻き付いている紐は、エルシーと虚ろなる瞳のようにしっかりと織り込まれている。しかしどういうわけか、エルシーがこの水着を着ると、かすかに猫の鳴き声が聞こえてくるんだとか。",
  str_pet_skin_desc_1500763 = "男性も日焼け対策に真面目に取り組むべきだと考えるクレーケンは、深海の冒険に適し、日焼けも防止できる勇者の水着3点セットを選んだ。\n影ノ街をイメージした配色が施され、クレーケン好みのスタイルが用いられている。さらに襟の開口部を深めにすることで放熱効果を高め、より多くの触手を収納することができるようなデザインになっている。また、日焼け防止用のジャケットが付いているため、太陽が苦手な彼でも海辺を自由に動きまわることができる。陸より水の中にいる時の方がリラックスしているように見えるクレーケンは、どうやらあなたと一緒に夏のひと時を楽しみたいようだ。",
  str_pet_skin_desc_1400863 = "潮汐祭をテーマにデザインされた、白い乙女シリーズのコーデ。ユーライアの立場を考慮し、無垢な純白を用いて純真さと敬虔さを表現している。彼女の周りには花のつるが軽やかに浮かんでおり、いつでも彼女の呼びかけに応えてくれる。一見普段と変わらないように見える彼女だが、静かに佇む花たちだけが、彼女が着なれない水着に恥じらっていることを知っている。晴れ渡った空、潮の香りを含んだ風、ひんやりと冷たい海水…そして彼女が手に持つ儀式用の剣をひとたび振りかざせば、美しい音楽が奏でられるのだ。",
  str_pet_skin_desc_1600023 = "すでに絶版となった啓光士官学校の旧実習用制服。巡回中に遭遇する様々な気温や環境に対応できるよう作られたトレンチコートと、身体にフィットするようなセットアップが特徴。元々のボトムスがヒイロのサイズにあっていないため、どんな状況にも対応できるように、革を使って腿に固定されていた。 赤い腕章は、その頃から彼女の変わらぬ意志を現していたようだ。",
  str_pet_skin_desc_1600113 = "キシローナがある場所へ行くために選んだ礼服。同僚の話によると、キシローナは毎年この時期に、この服を着てどこかへ向かうという…フォーマルなネックスカーフ、白夜城の貴族風のフリル、そして全体の統一感を強調する足首のデザイン…このコーデを見た誰もが、彼女はパーティに参加するのだと思うだろう。しかし、彼女の硬く寄せられた眉根が、決してそうではないことを物語っている。",
  str_pet_skin_desc_1500334 = "雲桜旅館の、バイスの身体の特徴に合わせて改良した女性用の浴衣。雲山を彷彿とさせるような、シンプルな色使いに、特色あふれる帯と帯飾り、可愛らしい鈴…いつもとは少し違うしとやかさを、何気なく添えてくれる。この浴衣を着る度、バイスはいつも、忘れられない大切な時間を思い返すのだ。",
  str_pet_skin_desc_1500423 = "「ヴィート軍曹！ウルヴ軍曹！」「潜水だ、息を止めろ！」バートンが口走る。バートンは今、大海原を征服しようとしている――爽やかな白シャツに、航海に適した縞模様のロングシャツを重ね、また、海の変わりやすい天候に合わせて、コートを羽織ることも忘れていない。そして…すでに黒ずんだ啓光のロゴ入りの軍帽も。この軍帽はバートンが決してお気楽なバカンスではなく、軍事任務を遂行していることを意味するものだ。",
  str_pet_skin_desc_1400853 = "クールなトップスとエレガントなスカートを組み合わせた、メランコリックでピュア、ちょっと不気味で美しいコーデ。 精巧に編み上げられた袖、荘厳な儀式を彷彿させるようなベールに、クールなブーツ……ジェーンのコーデは、驚きを与えてくれるだけではない。どうやら、スカートの裾に咲く花には、特別な意味が込められているようだ。ただ不思議なのは――常に傍観者であろうとする彼女が、このコーデを選んだ理由である。",
  str_pet_skin_desc_1600253 = "闇夜に降り立つ吸血鬼か、はたまた火の海の渡し守か。黒と赤を基調としたクラシカルでロマンチック、かつ不気味な魅力を持ったこの衣装は、ある壮大な劇のためにカロン自ら制作したものだ。彼は舞台監督であり、脚本家であり、主演でもある。観客はグラスを掲げて彼を讃え、開幕の時を待っていることだろう！",
  str_pet_skin_desc_1400573 = "昼下がりに見た素敵な夢。フィリスはモコモコのパジャマを着てベッドで丸くなり、熟睡していた。夢の中ではユミが自分を抱きしめて、髪を撫でている。彼女が心と体に感じる温かみは、暖炉にも似ていた。まるで、何もかもが昔のままであるかのように…",
  str_pet_skin_desc_1500923 = "「…ジロジロ見ないでよ…！」\nこれほどの窮地が他にあるだろうか？絡みついたイバラがセファーの両足を吊るし上げ、薄いストッキングや黒い生地がボロボロになっている。混乱の中でも、彼女は手に持ったワイングラスのバランスを何とか保っていた。上品で華やかなドレスだが、見た目ほど着やすいわけではなさそうだ。",
  str_pet_skin_desc_1401023 = "「燃える心」を体現したシンプルなこの服が、暗くて狭い地下闘技場で唯一明るい光を放つものだ。ファイターたちはリングに上がり、肉体をぶつけ、精神力の戦いを繰り広げ、血を炎のように燃え上がらせる。来るときは猛火のごとく、去るときは燃え殻のように。彼女は指を鳴らしながら、目の前のすべてを打ち倒そうとしていた。",
  str_pet_skin_desc_1600933 = "休憩中のミジャードは快適でややセクシーな服を着ることを好む。いつでも実験を始められるように、清潔な白衣も欠かせない。研究ひとすじの彼女は休んでいる時だろうと、自分の休憩室にいる時だろうと、研究と作業の手を止めたことはない。つまるところ、彼女の休憩室は怪しげな実験室と何ら変わらないのだ。",
  str_pet_skin_desc_1601113 = "普段は沈みがちなベリエも、海ではいくぶんか楽しそうだ。シンプルなデザインの水着ながら、ベリエのスタイルの良さを存分に引き出している。ただ、本人はそんなことを気にも留めず、砂の城作りに夢中になっている。彼女にとっては、それが海へ来ていちばん良かったことなのかもしれない。",
  str_pet_skin_desc_1600013 = "そっと指を触れると、鏡のような湖面に波紋が広がる。ナシリスは真っ白なマーメイドラインのドレスの肩に大きな毛糸のストールを掛け、湖をのぞいている。本来ならまるで極光さながらにパーティーの注目の的となるはずの彼女は、独り鏡湖へと抜け出して来た。ここは寒くて薄暗いながらも、喧噪や飾り立てられた偽りから離れられる、彼女だけの静かな楽園だ。",
  str_pet_skin_desc_1600014 = "「静かな湖畔に咲く、二本の綺麗な白い花を覚えているかしら？」\n「一本は無垢なる水仙、もう一本は純情なる百合」\n｢それぞれの見た目は違えど、魂の形はまるで同じ｣\n｢共に葉を茂らせ、花を咲かす。共に朝露を含ませ、根を絡ませ合う｣",
  str_pet_skin_desc_1600383 = "大ピンチ！ガルーがオモチャ箱に閉じ込められた！新年を祝うため、ガルーが用意したサプライズ。オモチャの中に埋もれる彼女がとても可愛らしい。祝日の雰囲気が出る赤と白の服に、ロボットアームにまで蝶々結びのリボン。しかし、手元の爆弾は、いくらなんでもやりすぎでは…",
  str_pet_skin_desc_1500993 = "アイリーナは恥じらいながらソファーの上で縮こまり、両の素足を晒している。無造作に置かれた靴と身に付けたドレスが、先程までの舞踏会の賑わいを物語る。「シンデレラ」の童話のように、美しい魔法のドレスは時間と共に失われていく。しかし、思い出は――今夜、あなたと過ごした時間だけは、消えることも、色あせることもない。",
  str_pet_skin_desc_1400453 = "大雪とともに、厳しい冬がやって来た。道には行き交う人もおらず、暖かい灯の光だけが瞬いている。もしあなたが独りこの地を訪れた旅人であったとしても、道に迷う心配はない。この道の角には――白い燕尾服に黒いブーツを履き、しっかりと撫でつけられた髪の、優雅な立ち居振る舞いと控えめな物腰の紳士が、馬車の傍らであなたを待ち続けている。",
  str_pet_skin_desc_1600193 = "炎に焼かれた薔薇が、花びらを美しく開いたまま灰となる。鏡に映し出される、美しくも邪悪な場景。ビクトリアは鏡の中の自分を見つめている。しかし、来訪者の気配に、彼女は後ろを振り返る。華やかなドレスの裾がひらりと舞い、深い眼差しの瞳が見るものを深淵へといざなう。",
  str_pet_skin_desc_1600263 = "存在の意義、虚無に対する認識……この不思議な服に着替えた後、漠然とした問いかけが一日中頭から離れなくなったウリエルは、ただ考え続けることしかできなかった。しかし、虚構に満ちた文学の世界でウリエルの求める答えは見つかるのだろうか？断言できることはない。それでもできることがあるとすれば、彼女が文学にふけっている間、彼女と共に歩み、共に考え、共に感じることだけだ。",
  str_pet_skin_desc_1400543 = "真面目で几帳面。それがナディーンの性格だ。疲れ知らずの彼女は、己の役割を全うしようと努力し続けている。いつもと違う、青春の雰囲気に満ちた衣装をまとっていたとしても、手に持つランタンが可愛らしく装飾されていたとしても、彼女のそうした雰囲気まで覆い隠すことはできない。",
  str_pet_skin_desc_1500883 = "青い空、白い雲、平坦な道――R・W砂漠とはまったく異なる風景だ。マギーもいつもとは違っている。きれいなセーラー服を着て、大きなリボンが風に揺れる。晴れた日の朝、食パンをかじりながら「のんびり」自転車に乗っている彼女は、始業時刻に間に合わせるのをあきらめたのだろうか？\nこの不思議な服は、R・Wの中でマギーをひときわ目立たせるだけでなく、彼女にいつもと違った光景を見せることもできるようだ。それこそがこの服の持つ魔力なのかもしれない。",
  str_pet_skin_desc_1600963 = "せ、先生？シャリーが？アルバイトとはいえシャリーは真剣らしく、わざわざ教師用の服に着替えている。確かに今のシャリーは以前よりもずっと頼りがいがあり、喋り方も落ち着いている。彼女の授業には、本当に学べることがあるのかもしれない。",
  str_pet_skin_desc_1601053 = "普段着でもイブはR・Wの人気者だ。どれほどの人気かは、彼女自身も分かっていないことだろう。皆を応援するという彼女は、どこから手に入れてきたのか分からない、変わった服に着替えたが、人気は下がるどころか、天元を突破する勢いである。ただし、決して彼女をまじまじと見てはならない。さもなくば、怒りに満ちた巨大なレンチが空から降ってくることだろう。",
  str_pet_skin_desc_1600064 = "ふんわりつややかな生地、いたるところにあしらわれたリボン…しかし、これは本当に「パジャマ」なのだろうか！？なぜ、こんな常識を超えたデザインの服が存在するのか、そして、これを人前に着て行っていいものなのか？カレンは困り果てた。どうするべきか分からずに、とりあえず着てみると、知性と厳格さにあふれたオーラを漂わせるカレンも、いつもと違った雰囲気に変わった。\nパジャマパーティのため、そして皆と打ち解けるため…カレンは思い切った冒険に出た。",
  str_pet_skin_desc_1600303 = "漆黒の着物、真っ赤な羽織。我こそ天下の悪人を成敗する者――赤浪サメ之助、参上！「郷に入っては郷に従え」、R・Wの首領として、自ら手本を実践するのが彼の流儀だ。着物に腰の刀と、どれも完璧なまでに雲島のおもむきを備え、笑い声までいつもより豪快になっている気がする。ただし、この流浪人は機嫌が良くなると、即興で作った俳句を大声で詠み始めることがある。皆の者、ゆめゆめご油断めされませぬよう…",
  str_pet_skin_desc_1400443 = "清々しい風が松林に吹き、暖かな日差しが室内を照らす。都会の喧騒と煩雑な業務から離れ、静かな「雲桜旅館」にやって来た。この機会にゆっくり休もうではないか。「ライフワークバランス」こそビビアンのモットー、そして1日女将の勤めは心身ともにリラックスできた。やる気を満タンチャージして、さあ、また仕事に戻ろう！\nもちろん、すべては計画のうち！",
  str_pet_skin_desc_1600643 = "ラスに支給された新しい「潜入用戦闘服」。東方の絹糸で織られた生地は軽く、身体にフィットし、ひらひらと揺れて美しい。軽装だが、その分動きやすく、ラスの戦闘力には一切影響をおよぼさない。\n拳を振るい、身体を動かし、勇んで前へ進み、すべてを打ち払う――どんな危険も、ラスさえいれば一件落着！",
  str_pet_skin_desc_1600893 = "珍しく休みのとれたイルンティ。休暇のために、雲島式の着物まで用意した。金色の生地と刺繍に真っ白な毛皮の肩掛けを合わせ、漂う優雅な華やかさ。さて、この服を着て、雲島の街をゆっくり歩いて回ろうか、それとも列車に揺られて景勝の地をめぐろうか…期待が彼女の胸をふくらませる。\nしかし、彼女の計画は突然の事件に狂わされた。せっかくの休暇を守るため、雲島の駅でイルンティのお取り調べが始まる…。",
  str_pet_skin_desc_1300653 = "「兄さん、うちと羽根つきしませんか？」\nタタがうきうきした様子で羽子板を抱え、近づいてくる。しかし、その笑顔の裏で燃えるのは、必勝の闘志。気楽な遊びと思っていたが、最後は手練れ同士の激戦に！？華麗なサーブと強烈なスマッシュが飛び交う、素人離れしたレベルの試合が繰り広げられる！\n負けると罰ゲームとして顔に落書きされるらしいが、タタがどうか落書きを手加減してくれますように…",
  str_pet_skin_desc_1600233 = "恥ずかしがり屋のクラリンだが、皆が「レース」を見に行ったと聞いて興味を抱き、ある商人に勧められて応援の仕事を引き受けることになった。しかし、普段の服装と比べると、コスチュームが少し「特別」で…\nだが、明るく元気な性格になりたいと考えたクラリンは、あえて挑戦することにした。",
  str_pet_skin_desc_1500843 = "「砂の熱さ、水の温もりと柔らかさを持ち、ヴィンテージの要素と新しい特徴を兼ね備えていること。」\n「粗野で礼儀をわきまえない物言い、無礼極まりない…」\nさまざまな評価があったものの、イスタバンがこの服を着ると、あらゆるマイナスのコメントが一瞬で消えた。華やかな場所にいなくても、見る人に名士の雰囲気を感じさせる。もしかすると、これこそが「シャドウマスター」のオーラであり、それが魅力を増しているのかもしれない。",
  str_pet_skin_desc_1600603 = "レースの審判は常に目立つ格好をしている。目にもとまらぬスピードで駆け抜けるレーサーにも見えるようにするためには、目立たなければならないのだ。\n酒代に困りレースの審判を引き受けたジョナは、すぐにうさん臭い裏事情を知ることとなった。本来なら余計なことに首を突っ込まない性分だったが、純真な少女のためにコースへ飛び込み、八百長レースに出場する悪党どもに「公正さ」を叩き込むのであった。",
  str_pet_skin_desc_1500713 = "灼熱の太陽が照りつける過酷な気候の中、レースカーさえ煙を上げそうになる。汗は砂漠に滴り落ちることもなく、たちまち蒸発してしまう。\nそれでもタキは「完全武装」でレースに出場し、スキをうかがうライバルたちを倒し、一気に優勝するつもりだ。彼がこれほど真剣なのは、お金のためだけなのだろうか？",
  str_pet_skin_desc_1400613 = "「ああ…これが大陸の姿なんですね！」\n雲間に浮かぶチャンドラ。高さを恐れることもなく、地上で開催されているラリーを興味深く眺めている。激しいレース展開を思わず実況してしまう彼女。しかし、この熱気球と、そのエキゾチックな服は…\nそう、これはすべて彼女の不思議な「心療セラピー」。溜まった負の感情を解き放つには、最適の方法なのだ。",
  str_pet_skin_desc_1600103 = "「きれいで清潔な服。それこそがメイドの誇り！」\nそれじゃあ、リタの手縫いのメイド服に着替えて、レースの縁取りがついたヘアバンドをつけよっと！あっ、そうそう。金色のリボンが縫い付けられたエプロンも、忘れずにね！\n今日のルイスのお仕事は…ご主人様のメイクのお世話、それからアフタヌーンティーの用意だね。心配しないで！ミツバチさんとシカの赤ちゃん、それからお空の雲さんも手伝ってくれるから。\nさあ、メイドさんのお仕事、始まるよ～！",
  str_pet_skin_desc_1600283 = "オッホン！それでは、アップトン荘園のメイド長をお迎えしましょう！…えっ、見覚えがある？その通り！我らがかわいいラファエルだ！\n彼女が最近受けていた特別任務は、白夜城のメイドたちを訓練し、ある程度の戦闘能力を身につけさせるというものだった。訓練期間も終わりに近づき、ラファエルの丁寧な指導により、メイドたちはメキメキと成績を上げていったが…ラファエルの方のメイド修行は、あまり順調ではないようだ。",
  str_pet_skin_desc_1400673 = "そよ風が吹くと、白くてふんわりしたスカートがかすかになびき、赤い花が顔をのぞかせる。アリスの衣装は不思議とケーキを連想させる…そう、誕生日にしか食べることのできない、あのイチゴのケーキだ！しかし、「幻のスイーツ屋」では、店主アリスの質問に正直に答えるだけで、大好きなスイーツを何でも無料で食べられる。それはアリスからの特別なおしお…いや、「ご褒美」なのだ。",
  str_pet_skin_desc_1601163 = "思い出の中の「あのパン」を作るため、フェラールは知恵を絞り、何度も試行錯誤を繰り返していたが、うまくいっていなかった。\n今日のフェラールの準備は今まで以上にばっちりだ。縫い目が整ったシャツ、アイロンがけされたエプロン、そしてピカピカに磨かれた革靴。美味しいパンを作るには、服装が大事と言われたからだ。あまり信憑性のない話だが、フェラールは思い出のパンのために、出来ることは何でもする覚悟だった。",
  str_pet_skin_desc_1601263 = "スランプに悩む売り出し中の恋愛小説作家が変装して街へ繰り出し、インスピレーションを探している。なぜ変装する必要があるのか？きっと、普段は凛とした商会の管理人が、プライベートで「乙女心」むき出しの趣味を持っていると知られたくないからだろう。\nしかし、この趣味に対するベセルの執着を侮ってはならない――彼女は創作のインスピレーションのためなら、自分の身の危険すらいとわないのだ…",
  str_pet_skin_desc_1500703 = "空気まで熱くなり、呼吸が荒くなるような気がするような視線…これは緊張だろうか？そうかもしれない。リオナほど強くて美しい者の前では、緊張しない人の方が少ないだろう。ストラップ式サンダルのひもが彼女の両足に絡みつき、いつものスタイルとはまったく異なるアクセサリーが体を飾っている。そして彼女自身は、世界のすべてを手に入れたかのような雰囲気でゆったりとたたずんでいる…",
  str_pet_skin_desc_1400813 = "これはヘールが「あるもの」を探すために用意した服らしい。動きやすい水着、彼らしいサーフボード、レインコートを参考にしてデザインされた透明な上着…透明？そう、ヘールの透明な上着を着ている本当の目的は、肉体を見せつけるためだろう――プロテインとハードなトレーニング、太陽と汗でできた彼の肉体が、賞賛の声を待っているのだ！",
  str_pet_skin_desc_1601123 = "最近、影ノ街に流れているウワサ。予告状、追っ手を手玉にとる怪盗、盗まれた宝石…犯人は我々の前で興味なさそうにしているスモーキーなのだろうか？真相を知りたければ、まずは彼女の手錠を外さなければならないだろう。もちろん、彼女の新しいあだ名と服も気になる。「怪盗クロネコ」は3日後に約束通り宝石を奪いに来るそうだ…",
  str_pet_skin_desc_1600384 = "水着が先だったのか、それともゲームが先だったのか？今さらどちらでもいいことだ。重要なのはこれを着たガルーが休暇モードになるということだ。つまり、これはガルーが休暇のためにわざわざ用意したものなのだ。たとえ、行先がビーチではなく、水族館だったとしても",
  str_pet_skin_desc_1400413 = "果たしていくつの顔があるのだろうか？白夜城のガイド以外にも、彼女には数々の副業がある。その1つが「ホテル・フルートプラチナ」のイメージキャラクターだ。この水着は広告の撮影時に着たもので、素材や裁断も洗練されている。青い海と青い空の下に建つホテルには、人々も心を奪われてしまうことだろう",
  str_pet_skin_desc_1500873 = "バーバリーが島の領地を巡察した時、現地に融け込むために着替えた甲冑のような水着。普段よりはずっとシンプルな着こなしだが、貴族らしいオーラは隠しきれない。これは武を貴ぶ家柄の影響というよりも、バーバリー自身が貴族としての名誉を追い求めた結果なのだ",
  str_pet_skin_desc_1601293 = "涼しげな夏の装いだが、ルークの真剣な眼差しが、くつろぐためではなく、重要な任務のために来たのだと物語っている。これは高温多湿な森の中で彼の体力を保つだけでなく、貴重な蝶を守り、恥知らずな密猟者を撃退するために用意された「礼服」なのだ",
  str_pet_skin_desc_1601483 = "砂漠の水祭りがまもなく始まる。しかし、多くの人がそれ以上に興奮しているのは、アズールの魅惑的なスタイルのせいだ！特に肌見せ多めの服を着た姿はなんとも…オッホン！皆さん、あまりじっと見過ぎないよう、視線にはご注意を。時には熱く湿った夜風に吹かれながら、騒がしい音楽に合わせて皆と一緒に踊るのもいいだろう！",
  str_pet_skin_desc_1600254 = "古き時代の貴族のようなたたずまいと華麗なステージの空気感…見るからに非日常そのものの衣装は、カロン自らデザインした舞台衣装である。誇張されたデザインもカメラの前に立てば、一気に観客の目を引き付け、役になりきったカロンの印象深い演技を一層と引き立てる。カロンも、この衣装も、まさに芝居のために生まれたかのようだ。",
  str_pet_skin_desc_1400683 = "さあ、買った買った！クーリエ隊と影ノ街の新聞社が提携し、クーリエたちは新しい任務――新聞購読のセールスを任されることになった。ウェンディは新聞配達用の制服を身にまとい、新聞を手に飛び回ってセールスに励む。常にスピード重視のウェンディは、新しい業務であろうと誰にも引けをとらないようだ。",
  str_pet_skin_desc_1501003 = "過去に縛られるスカーレイがいつもと違う服装に着替えた。一見、普通の医者のようだが、常に持ち歩く医療バッグが普通とは違う「業務内容」をうかがわせる。というのも、彼女が治すのは生きた人の病だけではない。亡くなった人の、「墓所」から響く声にも、平等に耳を傾けるのだ…",
  str_pet_skin_desc_1601203 = "友好を深めるための交流活動で、白夜城のヘイディは同僚たちの推薦を受け、交通安全と犯罪予防の意識向上を呼びかける「1日護衛官」になることに。啓光連邦のカナン城に出向いたヘイディだったが、そこでは白夜城の騎士といえども、啓光の制服に着替えなければならない。ヘイディ自身はどうもなじめないようだが、彼女の自信と魅力は変わることなく輝いている。",
  str_pet_skin_desc_1601193 = "記憶の中の魅惑の味を求めて、レビィは独り危険を犯し、監獄に潜入した。グレーゾーンで生きるさまざまな犯罪者が集まる監獄には危険がいっぱい…啓光連邦から混沌の地に足を踏み入れたレビィは、順調に目標を達成し、自らの潜入任務を果たせるのだろうか？",
  str_pet_skin_desc_1601194 = "ガルーは新型の装備を開発した。子どもたちの目に映るヒーローに変身できるものらしい。興味を持ったレビィは、すぐにガルーが用意していた部屋にやってきて、ガルーが用意した服に着替えた。それはヘルメットのついたつなぎ服で、レビィのような小柄な少女でなければ着られないようなものだった。同時に、レビィはガルーが自分のために準備してくれた最先端テクノロジー製品、「暗鬼クリーナー」を手に取り、自分だけのヒーローの旅を始めた。",
  str_pet_skin_desc_1601173 = "全身傷痕だらけでも、グラムは池の中に一人で立ち、自分だけの特訓を続けていた。彼にとって傷痕は勲章と名誉の象徴だった。周囲に建てられた武器は、彼がかつて戦場で過ごした激動の歳月を見届けてきた。戦士は不屈なのだ！",
  str_pet_skin_desc_1600234 = "海の雰囲気たっぷりの華やかなドレス、美しい飾り…この服を着たクラリンは、静かな海の仙女に変身したかのようで、注目を集めないように片隅に隠れることなど、もはや不可能だった。クラリンは一時的にこのドレスを借りるだけでよく、夢の中のものに執着する必要はないと言っている。しかし、目に見えない3人の仲間は、クラリンならきっと夢の中で手に入れたもの――たとえば彼女の愛と勇気を現実世界に持ち込めると信じている。",
  str_pet_skin_desc_1400163 = "一緒にフィジカルトレーニングをする約束をしていたカフカは、とっくにトレーニングメニューを終わらせていた。\nこの灼熱の砂漠の中、カフカはとても涼しそうな服を着て、涼しげなテントの中で休憩している。しかも、フランツをからかうことも忘れていない。彼女は時折横を見ている。明らかにこちらのことを心配しているようだ。",
  str_pet_skin_desc_1501653 = "シエルは崩れた洞窟の中にメカと一緒に閉じ込められ、上の隙間からは降った雪が少しずつ落ちてくる。\nしかし、幸いなことにシエルの着ている啓光のエンジニアリングスーツには防寒保温機能がある。\nしかも、メカの内部にはかすかな明かりが残されており、シエルは何も気にすることなく自分の研究をつづけた。唯一不満を言うならば、メカの中のスペースがとても狭く、シエルの両足を伸ばせないことくらいだろう。",
  str_pet_skin_desc_1601213 = "真っ赤な花びら、枝を埋めつくすトゲ…パロマのスタイルは、見る者にまるで「近寄るな」と告げているようだ。うっすらと浮かぶ笑みが、彼女の冷たく美しい危険な香りをさらに際立てる。軽率に怒らせてしまえば、恐ろしいことになりそうだ。影ノ街の組織のボスたちが敵を片付けるように…それとも、彼女はもうすでに…",
  str_pet_skin_desc_1500123 = "カナン城でにわかにささやかれるようになった「正義執行、a.k.a.天罰代行」のウワサ。規律を守らない者がいると、突如雷鳴と共にナミシスが現れ、罰を与えるという。そして、相手の心を刺すラップで相手を悔い改めさせ、「正義」の執行を終えると、再び起こった雷鳴と共に一瞬で姿を消し、また別のところへ向かうのだとか…",
  str_pet_skin_desc_1600773 = "ベツレヘムとあなたはチャーヤの古いノートを見つけた。チャーヤは自身の使命を知っていた。だからこそ、少なくともその瞬間がやってくるまで、まったく違う未来を想像していたい――画家になる未来、詩人あるいは歌手になる未来、それは今しか見ることのできない白昼夢だ。しかし、2人が物語を読み終わる前に、古いノートは年月の浸食を受けて破片に変わり、美しい過去と想像に満ちた未来と共に消えてしまった。\n「…別の未来があってもよいかもしれぬ」ベツレヘムはアストラで成功した歌手に関する情報をあなたに尋ねた。それを素材に、チャーヤの夢の続きをつづるのだ。",
  str_pet_skin_desc_1400833 = "「リリ」を覚醒させるためにできることは…アイドルになること！？メイドのルールをかたくなに守り続ける彼女たちは、果たしてアイドルになれるのだろうか？なんといっても、アイドルには生き生きとした魅力と創造性が必要なのだから。だが、一連の行動基準と数の優位性があれば、可能性もゼロではないかもしれない…",
  str_pet_skin_desc_1601313 = "音楽に垣根はない。ノーヴィオはこの日、いつもとは全く異なる服を身にまとい、ピアニストに変身した。そして、北境で強くたくましく暮らす人々にあたたかい祝福を届け、一縷（いちる）の期待を抱く特別な観客に励ましを贈った。これからの日々も、人々が強くたくましく暮らしていけるように。",
  str_pet_skin_desc_1601383 = "上司と色々あって参加したアイドルオーディションではあったが、シヴォーンは相当の準備と訓練をして臨んだ。衣装もコストを惜しむことなく、精魂込めて研究しデザインしたものだ。そうした科学者としてのプロ意識がもたらした効果は、まさに驚くべき大変身！誰も止めることのできない光り輝く魅力は、まさにスターへの階段を予感させる…",
  str_pet_skin_desc_1600273 = "白夜城の恋人たちの間でささやかれる恐ろしいウワサ――毎年冠月祭の季節になると、白い服をまとった騎士が白夜城の隅々を巡回し、熱愛中の人々を見つけると「恋愛禁止告知書」を突き付けるという。こうしてこの騎士は恋人たちから「恋を断ち切る雷光」と呼ばれ、恐れられるようになった",
  str_pet_skin_desc_1500553 = "普段の厳かな服装と違い、今日はピアタマンも街の冠月祭の空気に影響されたのか、いつもの毅然とした雰囲気の中にも優しさを感じさせる装いをしている。もちろん、意中の人に会うためではない。ある人の願いをかなえるため、使者としてふさわしい服装を選んだのだ",
  str_pet_skin_desc_1400913 = "クロエにとって、愛は常に別れと共にある。そんな彼女に幸せいっぱいの愛をたたえる曲を演奏させるのは少々無理がある。ならばいっそのこと、神の名において、永遠の愛をたたえよう――人々の抱く愛は限られた月日の中に消えていく。だが、それでよいのだ。光はいつでも平等にこの世のすべての者を祝福し、愛してくれる",
  str_pet_skin_desc_1601673 = "この手の社交場には数々の小さなマジックが存在する。そのタネは「秘密」。1枚のカード、1つの言葉、そして視線…宴はたけなわ、誰も気づかぬ間に、壮大かつ巧妙なパフォーマンスはすでに完成している。ジェノにしてみれば、いつもの拍手喝采には欠ける。だが、たまには友人に恩を売るのも悪くない。",
  str_pet_skin_desc_1600043 = "冷えきった遺体、証拠の横に置かれた札やチョークのアウトライン、そして規制線…よく見る典型的な疑惑漂う事件現場に立てば、様々な憶測が浮かんでくる。「探偵が犯人ではないか？」、「探偵は犯人と通じていたのではないか？」、「犯人は身近な者の中に潜んでいるのではないか？」、さらには「証人がすべて犯人」なんてことも…だが、いったい誰が想像しただろう？被害者と探偵が仲間だったとは…",
  str_pet_skin_desc_1400483 = "穏やかな影ノ街にひそかに漂う不吉な空気。静かな夜を楽しむ道行く人々の中で、鋭いパトロールの眼差しはわずかな罪悪も見逃さない。罪悪が潜むかぎり、この街の平和を守る彼女は歩みを止めることなく、パトロールは永遠に続く。それもこれもすべて…かけがえのないたった一人の妹のために！",
  str_pet_skin_desc_1601484 = "整然と明るい事務所、柔らかいソファー、心も酔いしれるような美酒、そしてソファーにもたれかかる「マネージャー代理」…彼女のけだるい雰囲気に騙されてはいけない。この美女には危険な香りが漂っている。特にこれからやってくる獲物には…本当の「危険」が待ち受けているのだ",
  str_pet_skin_desc_1601663 = "「うーん…かわいい子たちはどこにいるんだろう？」珍獣を探し出し、真相を突き止めるため、探偵に扮したフィアが「事件」調査に挑む！集めた証拠を分析し、怪しい点を洗い出す…調査に没頭する真剣なフィアの姿を見ていると、本当に何か発見できそうな気がする。",
  str_pet_skin_desc_1500983 = "引きこもりがちなクスッタはシャドウマスターの命によりやむをえず、最近街にのさばる犯罪者を追う探偵となった。もちろん、クスッタは聞き込みや事情聴取が得意ではない。だが、鋭い彼女は独特の「安楽椅子」に座ったまま、机上の手がかりだけで事件の全体を見通し、思考によって犯人を突き止めるのだ。",
  str_pet_skin_desc_1601034 = "この世に生きる誰しも、罪を犯すべきではない。罪を犯せば、必ず天罰がくだる。人の世において、それは尋問、審判、懲罰として現れる。とはいえ、その過程はそう恐れるほどのものでは無い。エルシーは尋問官として、優しく、暴力を一切用いることなく、相手の心の壁を崩していく…そんなもの、そもそも彼女の前では無意味なのだが。尋問官エルシーを前にした時は、抵抗をあきらめ、すべてを彼女に委ねよう。",
  str_pet_skin_desc_1400623 = "リアの勉強会が順調に進むよう、シルヴァはわざわざ正式な服装に着替えた。これから先生に会いに行く若手学者のような服装は知的で聡明な印象とともに、粛然とした雰囲気を漂わせている。シルヴァのこうした態度は当然勉強会にもよい空気感をもたらした。シルヴァはまさに「模範生」と言えるだろう…",
  str_pet_skin_desc_1300463 = "大人たちにとっては恐怖の対象である黒魔術の本も彼らにとっては神秘の世界へと続く入口だ。そこにはたくさんの幻想と魔法、不思議が満ちており、まさに彼らのような好奇心あふれる、かつ高慢な魂のために用意された世界だ。「禁じられた魔法の薬」を作ろうと、様々な奇妙な材料を探し回るため、専用の服装に着替えた彼らはいつも以上に個性豊かな姿となった。",
  str_pet_skin_desc_1600293 = "「先生」の願いをかなえるため、ガブリエルは厳かな礼服に着替え、影ノ街にある孤児院へと向かった。薄暗く、荒れ果てた環境と精巧な作りの礼服とのコントラストに、ガブリエルのゆったりとした話し方や立ち居振る舞いが加わって、子どもたちはガブリエルを「魔女」と勘違いしてしまう。しかし、最後には彼女のこの地を守りたいという気持ちが子どもたちに伝わり、礼服にも心やすらぐ輝きがきらめいたように見えた。",
  str_pet_skin_desc_1601433 = "夜の森を突然の雷雨が襲うと、不吉なものがこの世に現れるという。リンネは厳かな巫女の衣装をまとい、神楽鈴を掲げ、穢れを祓い、衆生を救う。\n「…即ち陰陽を誦み、此の曲、汝の魂と伴に彼岸へと帰らん…」\n「三途の川の下にて、曲の幽生なるを怨み…」\n「曼荼羅は語り、琴瑟は和して鳴する」\n「聴く者の心を寧んじ、吾が魂は満たされり…」",
  str_pet_skin_desc_1601214 = "水着姿のパロマはセクシーかつ神秘的な魅力を放ち、人々を魅了する。その魅力のとりこになった人々は彼女を女神と崇め、跪き崇拝する。しかし、パロマはそうした盲目的な崇拝を最も嫌う。鋭いトゲをもつイバラのように、盲目的な信仰の愚かさを暴き、軽々しく近づこうとする者たちに苦しみを与える。",
  str_pet_skin_desc_1601054 = "虚構の夢の世界は消え、愛する人とあの白い花を探す彼女は痛みに向き合う決心をする。偽りの幸せと美しい夢で編まれた籠を破り、誰の人形でも駒でもなく、生きて行こうとする。そして彼女はようやく夢を実現した――本物の日の光を浴びながら、本物の花畑の中を駆け、小さな願い事をする。",
  str_pet_skin_desc_1601403 = "ある海底遺跡を調査するため、フロリナは自ら深い海の中へと潜っていく。短い準備時間で何とか準備したのは少し変わった水着だった。デザインも材質も、どうやら別の遺跡のもののようだ…そして、その水着はフロリナのもう1着の変わった服装とよく釣り合っている。同じ遺跡で見つけたものなのだろう。",
  str_pet_skin_desc_1601153 = "クーリエ隊はいつでも多忙だ。仕事熱心なナルセールがいくら努力し、奔走し続けようとも、対応しきれない時もある。気分転換のため、桟橋のかかる夏の海にやって来た彼女は果てしなく続く海と空を眺めながら、砂の匂いの混じる潮風を感じていた。ひと時の静けさを堪能しているようだ。",
  str_pet_skin_desc_1400793 = "R・W砂漠にやってきたミジェンニは砂漠の環境に溶け込み、誰かに注目されて、不必要な面倒に巻き込まれないよう涼し気な服をまとった。何しろここは文明の満ちる白夜城ではなく、あちこちに荒々しさが満ちる砂漠である。ミジェンニにそんな危険な砂漠に足を踏み入れる決心をさせたのは、ある特別な猫だった…",
  str_pet_skin_desc_1600774 = "北境の氷と雪は権杖だけでなく、分厚いマントも編み上げる。冷ややかな権杖を手に持ち、マントをまとうベツレヘムを見ながら、人々は思わず想像する――もし冬が過ぎて春が訪れ、日差し輝く夏がやってきたのなら、ベツレヘムの仮面も融けるのかと。暑い夏の日の夕方、海風は彼女の羽を広げ、笑顔を引き出し、太陽の下で輝かくすべての生き物のように生き生きとした姿を見せてくれるのだろうか？",
  str_pet_skin_desc_1601783 = "金貨が山のように積みあがり、宝物があたりに散らばる。伝説に残る最後のウロボロスの守る秘宝が、突如として姿を現した！勇敢な冒険者たちは、わずかな手がかりをもとに数々の危険を乗り越え、ウロボロスから宝を持ち帰ることができるのか？それとも宝の目の前で、ウロボロスの腹に飲み込まれてしまうのか？",
  str_pet_skin_desc_1501573 = "サナエはニナが貸し切った私立博物館で目を覚ました。眠気さめやらぬサナエはどこか不気味な博物館から立ち去ろうとする。だがその時、近くにあった操り人形が気味の悪い笑顔を浮かべ、暗闇の中から足音が聞こえてきた…足音はますます近づいてくる…",
  str_pet_skin_desc_1500563 = "長い間客地を旅していたコンスタンはしばらくぶりに故郷へと戻った。身なりを整えた彼の手に握られた武器はすでに標的を絞っている。暗鬼がどれだけいようとも、コンスタンは1匹残らず片付ける。この地に過去の悲劇が二度と起こらないように。",
  str_pet_skin_desc_1602113 = "100年前で止まった時間、残るのは思い出だけ。\n楽しい夏の終わりの日のはずが、雨天に見舞われ、浅瀬に立ったザーリャは心残りばかりの過去と二度と会えない家族を思い出していた。",
  str_pet_skin_desc_1600894 = "イルンティは父親への複雑な感情のため、金色の波紋の下に広がる夢に陥ってしまった。彼女はそこで初めて法廷に入る法廷の騎士となり、潜在意識の導きに従い、父親がかつて関与した事件を再度調べることになった。公平とは何か？正義とは何か？イルンティは手に持つ剣と杖を使い、この不落の城を支える天秤を作ることを誓った。",
  str_pet_skin_desc_1601563 = "ちりばめられた琥珀もニナがまとえば、美しい衣装そのもの。カメラの放つ強い光に合わせて、ニナはスポットライトの下で向きを変え続ける。ほんのわずかな違いがジュエリー大会での勝利を決定づける。ニナはこの大会で誰よりもきらめき、ダイヤのごとく輝かなければならない。",
  str_pet_skin_desc_1400544 = "伝説の龍州の灯台は風も波も恐れず、海と共に生きる者たちに暖かさと心の癒しをもたらすという。今ナディーンはまさにその灯台だ。夜の訪れとともに海に霧が漂い始めると、ナディーンは明かりを手にし、希望の灯台となる。それは彼女自身の望みでもある。果てしない大海原で道しるべとなり、船と疲れ迷う人々を導き、無事の帰航と祝福をもたらす。",
  str_pet_skin_desc_1601883 = "12歳の幼きタンドウは天女のように夢の中で舞い踊る。その舞いに合わせ、海面には光の粒がきらめき、山脈のように起伏豊かな波はおぼろげに美しく、まさに夢の中の少女そのものだ。風に乗って進む船もまた、魚の群れのように波をかき分け進んでいく。そして未来の彼女は自らの手で己の夢をかなえ、はるか遠くの地に大きな繁栄をもたらすのだ。",
  str_pet_skin_desc_1600964 = "誰もがよく知るある事情から、シャリーはまた新しい副業を見つけた。今回の仕事先は多くの人で賑わう豪華な娯楽場だ。中はどこもかしこも自身の成果と運の悪さを悔しがる客でいっぱいだ。きっと給料もいいことだろう。しかし、この仕事をするには指定された非対称の要素にあふれる服を着なければならない。苦痛以外の何ものでもない。仕方なく服を着て仕事に臨むシャリーだったが、その後ハチャメチャな経験を積むことになる。",
  str_pet_skin_desc_1600065 = "郷に入っては郷に従え――ふとした縁のめぐり合わせで、カレンは龍州大陸の服を着ることになった。意外にもよく似合った重厚感のある服には武器も付いており、着心地もよく、使いやすい。だが、龍州の服を着たカレンはどうやら侠客と間違われてしまったようで、「江湖」と呼ばれる謎の場所に行くことになる。そこで招かれざる客と訳の分からない争いに巻き込まれるのだが…",
  str_pet_skin_desc_1500335 = "はるか遠くの龍州大陸には「龍女」の伝説が言い伝えられている。龍女は天候を司り、航行の安全を守る。人々は特別な時機に儀式を行い、龍女の恩に感謝し、その功績をたたえる。儀式では舞いに長けた少女が特別な衣装をまとい、伝説の龍女に扮して大海原をなだめるように軽やかに舞い踊る。",
  str_pet_skin_desc_1601723 = "孤児院から出演依頼を受けたリリカは、心を込めて着飾り、最高の状態で、華やかで完璧なパフォーマンスを子どもたちに届けたいと思った。祝日の雰囲気に合わせたステージになるよう、最も相応しい装いを選んだリリカ。しかし、この衣装は防寒には優れていないらしい。案の定、風邪を引いてしまった。",
  str_pet_skin_desc_1501873 = "きらびやかな海底の宮殿――竜宮で、テンカンは真珠貝の椅子にけだるそうに腰掛け、たくさんの金銀宝石の付いた装いに、満悦の笑みを浮かべる。深海の竜宮へ行き、賓客のもてなしをうけたことがあるとテンカンは言うが…彼の言葉を本当に信じていいものか？",
  str_pet_skin_desc_1400733 = "アストラ大陸の2匹の「ワンコの門番」は、異郷にやってくると、土地の人々から伝説の「黒白の双狗」に間違われてしまう。誤解は解けたものの、本人たちはそのまま「黒白の双狗」になりきり、人を見かけるたび「黒き祟り神パテ、遭いては諱み、遭いては斂める。白き祟り神パシ、遭いてはこれに供え、遭いてはこれに祈る」と唱え続けた。",
  str_pet_skin_desc_1600024 = "雲島の山神の封印に異変が生じ、手紙を受け取ったヒイロは状況を調査しに向かうことにした。前回立ち去るとき、櫻花一族が残していた盛装をお婆さんから渡されたが、ヒイロはまだそれを着たことがなく、お婆さんの優しさに感謝の意を伝えたこともなかった。今回の旅で、彼女はこの盛装を身にまとい、久しく離れていた故郷へあなたと一緒に再び帰ることを決めた。",
  str_pet_skin_desc_1601703 = "ポルクスは過去のことを話してくれた。その年、かつて賑やかだったユーフォリアは荒れ果てた廃墟となり、崩れた壁の中は武器の破片や子どもたちの泣き声で満ちていた。そして、その年にポルクスは前任者の遺志を継ぎ、守護者としての重い責任を担うことを決めた。今、彼女が守ろうとする未来にはあなたがいる。",
  str_pet_skin_desc_1500994 = "龍州出身のその女性雇用主は羽振りがよく、双閣港で最も上等な仕立て屋でアイリーナにこの服を用意した。シルクの生地は柔らかく、上品な織物になっており、巧みに飾りつけられた装飾品が肌の傷をうまく隠している。彼女を見た人は誰もが、彼女のことをか弱い箱入り娘で、姉と一緒に気に入った産業を見に訪れていると思うだろう。このようなカモフラージュは、彼女がひそかに潜入して調査する任務に大いに役立った。",
  str_pet_skin_desc_1602163 = "混沌とした太古の時代、人々は星を目印にして万物を測ったと言われている。しかし星々はあまりに高く遠いため、どれほどつま先立ちをしても、腕を伸ばしても、触れることはできなかった。それゆえ星空は、陸上の生物が共に憧れる夢となった。今、センキョクは星図の一部を取って傘に置き、あなたのために風雨に侵されない世界の一角を作った。",
  str_pet_skin_desc_1401273 = "幼い頃のパソロの願いは、両親と砂漠を離れて蝶を見ることだった。しかし、大人になった彼女は一人で旅立ち、そしてあなたと出会った。春新節の喧噪の中、紙の蝶がひらひらと宙を舞い、彼女はあなたと家族になる約束を交わした。",
  str_pet_skin_desc_1500093 = "文字。それは真理の火花である。文字があってこそ、先人たちの知識が残され、蓄積され、時間の激流を越えて、千年後も詠唱される詩となるのだ。学者の身なりをしたファウストは、今日も双閣港で文字と真理の神秘を探求している。",
  str_pet_skin_desc_1600264 = "虚無に耐えられないウリエルは、魔法薬を使って自分を他の存在に変えたいと思っていた。しかし、魔法薬を飲んだ彼女は願いを果たせず、不思議な酩酊状態に陥った。もともと意気消沈して孤立気味だった彼女だが、突然積極的になり、あなたを巻き込んで型破りなことを試し始めた。あなたはこれからまる一日、どう対処するのだろうか？",
  str_pet_skin_desc_1601753 = "「バラが枯れた後、アクセリアも完全に壊れるでしょう」\n戦闘で負傷したアクセリアは病床で目を覚ますと、ベッドのそばにガラス容器で丁寧に育てられているバラを見つけた。その瞬間彼女に、なぜか自分はまもなくスクラップにされる運命なのだという考えが浮かんだ。あなたは、冠月祭のプロモーション用にバラを送ったことや、運命、バラ、彼女の関係についてきちんと説明しようと考えている…",
  str_pet_skin_desc_1701073 = "「名高き我らが英雄を迎えよう。無数の戦いを経て、今凱旋の日を迎えた彼は我々に勝利をもたらした！耳を澄ませ、目を見開くがいい！この街のどこもかしこも彼の名を呼ぶ声で満ちている。アドラス！アドラス！栄光と幸福の高みへと向かう！」",
  str_pet_skin_desc_1600114 = "礼服を着たキシローナが遺跡内をさまよっている。龍の像の下には、彼女の古代の一族に関する情報が埋まっているかもしれない――彼らはこの謎の龍の力をどう見ているのか。または力に呑み込まれた疑いがあるのだろうか。古い誓約は歴史の風に吹かれ、強い将軍をいっそう不安にさせた。今あなたは彼女に新たな誓約を与え、再びその信念の火を点せるだろうか？",
  str_pet_skin_desc_1401013 = "いたずらをして面倒を引き起こしてしまったアンシアは罰として儀仗隊で訓練を受けることになった。彼女の最終的な訓練の成果がどうなるのか、どうぞお楽しみに。",
  str_pet_skin_desc_1500783 = "影ノ街の片隅で、快適で個性的なカジュアルウェアのロビンが静かな時間を楽しもうとしている。ずっと人を寄せ付けない態度を取っていた彼女が、自分からあなたを家に招待するなんて？",
  str_pet_skin_desc_1601164 = "フェラールが興奮しながら水から出てきた。手には引き上げたばかりの部品を握っている。彼の髪の毛からは水滴が落ち、熱い眼差しをこちらに向けている。このような夕暮れの光の中で、彼の胸の中では一体どのような感情がうごめいているのだろうか？",
  str_pet_skin_desc_1601773 = "ゴルディのファン大賞を引き当て、「1日プロデューサー」となったあなたは、忙しいアイドルの仕事だけでなく、彼女の生活の面倒も見なければならなくなった？暖かい家に帰り、かわいいパジャマに着替えたゴルディは、自分の感情をあなたと共有したいと思っている。",
  str_pet_skin_desc_1500924 = "セファーはついに単独で任務を遂行するチャンスを得ました！次のパーティーの仕入れをすべて任されたのです。仕事を有利に運ぶため、彼女は長年ため込んできたヘソクリを持ち出し、リッチな腕利き商人に扮しました。この姿ならセファーを見くびっていた商人たちも彼女を過小評価できませんよね？",
  str_pet_skin_desc_1601823 = "「秘伝のレシピによれば最も美味なスープが採れる上質なタニシは、この川にいるらしい」\nユエとあなたは森の川岸に行って、いっしょに夢のように美味しいタニシを探します。",
  str_pet_skin_desc_1602233 = "「君がため編みし厄除けの紐、五色に千の春を願う」\n龍州の五色祭で、あなたはシンゲイと「ある願い事」を探す冒険に出ます。世の中では誰もが何かを願っています。そして心優しき龍王様の前でもう一度祈るチャンスが与えられた時、あなたは何を願うのでしょうか？",
  str_pet_skin_desc_1400403 = "ボンバーは偶然「バーベチュー」という古い言葉を知りました。これは超激しいバーベキュー方法らしいのですが…キッチンが吹き飛ばされたら大変ですよ！",
  str_pet_skin_desc_1500363 = "影ノ街ではぐれたオオカミを探すヒドライ。彼はオオカミに危害を加える者たちと戦い、数少ない「仲間」を守ることに尽力しています。一匹狼を誇る彼ですが、他者との予期せぬ出会いに無意識のうちに抵抗することをやめていました。オオカミは群れで行動する動物であり、どんなに否定しようとヒドライも例外ではないのです。",
  str_pet_skin_desc_1601993 = "澄み渡る空の下、古代文明の痕跡の上には青々とした草木が生い茂る。\n空に響く鳥の声はまるで今を謳う讃美歌のよう。いつもは厳格なインゲルも今日は少し肩の力を抜いて、道端で何かを見つめている。その視線の先にあるのは青空なのか、それとも空を飛ぶ鳥たちなのか、あるいは誰かとの出会いを待っているのか…\nやわらかな風が2人の視線を引き合わせる。さあ、空へと飛び立とう。自由の歌がやまぬうちに、彼女と一緒に…",
  str_pet_skin_desc_1500424 = "ゆったりしたショートジャケット、ハードで頑丈なデニムパンツと革のショートブーツ――それがバートンが入団時に身につけていたものの全てだ。\nそのシンプルなアイテムが、勇壮な志を抱く一兵卒から堂々たる大軍の大将へと成長する彼を見守ってきた。",
  str_pet_skin_desc_1601553 = "ゆったりしたショートジャケット、ハードで頑丈なデニムパンツと革のショートブーツ――それがバートンが入団時に身につけていたものの全てだ。\nそのシンプルなアイテムが、勇壮な志を抱く一兵卒から堂々たる大軍の大将へと成長する彼を見守ってきた。",
  str_pet_skin_desc_1601843 = "うららかな風の舞うビーチ。水着選びの狙いが「心の扉を開く」だとしたら、素敵な展開が待っているかも！？\nどういう手違いか、イェリアは大胆な水着をまとっていた。そんな彼女を、あなたは他の海水浴客の視線から守る。\nその光景を目にするのはあなただけ…それは、本当に手違いなのだろうか？",
  str_pet_skin_desc_1601533 = "タキシード――それはひるみ、たじろぎ、自分を疑う者を丸呑みにする怪物。だがレインハトには進んで服従し、彼女の強さや風格を際立てることのみに集中する。\n仕立てのよい体に合った服は、鍛え抜かれた肉体を余すことなく引き立てる。すっきりしたデザインは古びることなく、時代を牽引する彼女をどこまでも搔き立てる。\n彼女にとって今夜、礼服は戦闘服、グラスは長槍だ。武装を整え、パーティーに乗り出す。彼女は啓光の大元帥、未来を注視する外交家だ。",
  str_pet_skin_desc_1500903 = "焼けつく日差し、果てしなく広がる海。そして…熱く燃え上がるステージ！\n可愛らしさを残した女性らしいステキな衣装をまとい、夏の祭典で盛り上がる海辺へとやってきた。情熱あふれるステージで、バーバラはまた多くのファンを魅了する。",
  str_pet_skin_desc_1400173 = "夏の海辺では、可愛らしいユニフォームを着たラビが看板店員として元気いっぱいに駆け回り、R・Wグルメで客に笑顔を届けようとしている。\nでも「悪魔のチリ地獄バーガー」の辛さはラビの情熱に負けない熱気を放ち、R・Wグルメの宣伝のはずが、いつの間にやら激辛チャレンジに…この辛さに耐えうる挑戦者はいるのか？",
  str_pet_skin_desc_1601863 = "春はピクニックにふさわしい季節だ。柔らかな日差しと風に包まれて、おいしいお菓子をあなたと一緒に楽しむ時間。\n彼女の気持ちは、思い人に届くのだろうか？結果はどうであろうと、共に過ごす時を大切にしたい。せめて、このうららかな春のひと時を無駄にしないためにも…",
  str_pet_skin_desc_1501004 = "黒箱の中にあるのは、夏の花火も届くことのない星空の墓所。あなたの進入に、その謎めいた美しさも、この場所を守る者も驚き、乱れる。\n魔力の満ちる沼は、黒い紗をあしらった水着姿をことのほか美しく映し出す。だが、寄り添うならば、気をつけなければ。あなたの訪れを心待ちにしていた彼女も、あなたが副葬品になることは望んでいないのだから…",
  str_pet_skin_desc_1500213 = "海に情なくも、花に情あり。\nバラの花に囲まれた孤島に悲し気で美しい人影が浮かぶ。華麗な海を創り出した彼もまた水に濡れ、きらびやかな景色の一部となっていく。\n完璧な芸術を完成させるには、ピースがまだ1つ足りない。あなたも傑作の一部になってみては？",
  str_pet_skin_desc_1602333 = "太陽に照らされ、砂浜がキラキラと輝き、青い海も眩しかったけれど、それよりも輝いていたのは少女の笑顔です。夏の冒険は終わろうとしていますが、大切な思い出、そして記憶の中の「彼ら」はいつまでも彼女の心の中で輝き続けます。",
  str_pet_skin_desc_1501903 = "華やかな美しい庭園に嵌め込まれた宝石も、太陽のきらめきと波のゆらめきの中でこそ美しく輝く。だが時として、ただそこにいるだけで、美しい輝きを放つ人がいるものだ。\n日々の生活に追われるあなたとのんびりと休暇を過ごすマシュー。2人が偶然出会った時、そこにはどんな挑戦が待ち受けているのだろうか？",
  str_pet_skin_desc_1602273 = "海風が悠々たるメロディーを吹きならし、波がハヤブサの翼を洗い清める。少女はサーフボードを翼にして波の上を飛びながら、海水の弾丸を銃へと込める。のんびりとした休日であるが、脅威がないとは限らない――彼女の輝く笑顔こそが最大の脅威である。気を付けるのだ、彼女の水鉄砲は決して容赦をしない。",
  str_pet_skin_desc_1601733 = "満月の夜、冷たい月の光が煙霧を破り、薄暗い火の光が誰かのすすり泣きと共に揺れている。心行くまで楽しんだ彼はまるで古城に咲く孤独なバラのようだ。上品で整った礼服の下には、着替えの間に合わなかったボロボロのシャツが隠されている。彼は月光越しに横目で見た。\n「食べ物を目の前にして、ずっと我慢していられるわけじゃない」",
  str_pet_skin_desc_1602183 = "やわらかいソファの上、軽やかな生地で仕立てられた華麗な礼服はシェオルの美しいボディラインを引き立てている。赤ワインの芳醇な香りと部屋に満ちた黄金色の光が相まって、酩酊した聖なる蛇は気だるそうに酒に浸る。それは美しくて危険だ。あなたの視線を感じとった彼女は微笑み、あなたを誘った。",
  str_pet_skin_desc_1500973 = "「魂の救済は肉体の治療よりも重要だ」\n凍えそうな夜、柳葉の氷刀の切っ先が閃く。重いものがズシンと落ちる音と共に、刺客の影も夜の闇に隠れた。彼は優れた医師だ。苦しみの根源を取り除いてこそ苦しんでいる人を本当に救えるのだと、よく理解している。",
  str_pet_skin_desc_1400953 = "街のネオンでは荒野のさすらいのヒーローを引き止めておけない。その謎めいたヒーローの正体を知る者はいない。しかし彼女は行く先々で群衆の注目の的になる。それは彼女の隙一つない身なりのせいというよりも、風のように自由な彼女の魅力のせいだ。",
  str_pet_skin_name_1602063 = "碧い休暇",
  str_pet_skin_desc_1602063 = "何も考えず、ただ寝そべることほど心地いいことがあるだろうか？\n任務も戦いもない。わざわざ意味など探す必要もない。\n——今この瞬間意味があるのは、ただ何もかも忘れて楽しむこと。\nほら、空をはばたくハトも「そうだ」と言っている。",
  str_pet_skin_name_1701103 = "静かなる聖女",
  str_pet_skin_desc_1701103 = "北境は極寒の地だが、人々は吹雪の中で鍛えられながら前進していく。彼らによれば、その信念は聖女の導きによるものだそうだ。\nしかし彼女は言う。彼らは嵐、雷、厳しい寒さ、果ては憎き暗鬼まで克服してきたのだと。この偉業は贈り物などではなく、彼ら自身が作り上げた奇跡なのだ。\n「あたくしは自分の使命を終えたし、本当のリーダーは彼らの中から誕生するでしょ」\n彼女の物語が終わり、心に満ちていたさまざまな雑音がすべて静寂に変わったとき、その顔は心からの笑みで輝いていた。"
}
return config
